package com.example.bandlink.controller; import com.example.bandlink.dto.ApiError; import com.example.bandlink.service.*; import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import java.util.stream.Collectors;
@RestControllerAdvice public class ApiExceptionHandler{@ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<ApiError> validation(MethodArgumentNotValidException e){String m=e.getBindingResult().getFieldErrors().stream().map(x->x.getField()+": "+x.getDefaultMessage()).collect(Collectors.joining(", "));return ResponseEntity.badRequest().body(ApiError.of("VALIDATION_ERROR",m));}@ExceptionHandler({PostService.RuleViolationException.class,IllegalArgumentException.class}) ResponseEntity<ApiError> rule(RuntimeException e){return ResponseEntity.status(HttpStatus.UNPROCESSABLE_ENTITY).body(ApiError.of("RULE_VIOLATION",e.getMessage()));}}
